alter table public.profiles enable row level security;
alter table public.user_roles enable row level security;
alter table public.customer_addresses enable row level security;
alter table public.merchants enable row level security;
alter table public.stores enable row level security;
alter table public.riders enable row level security;
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.order_groups enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.order_events enable row level security;
alter table public.payments enable row level security;
alter table public.payment_events enable row level security;
alter table public.ledger_accounts enable row level security;
alter table public.ledger_entries enable row level security;
alter table public.refunds enable row level security;
alter table public.merchant_settlements enable row level security;
alter table public.delivery_jobs enable row level security;
alter table public.delivery_stops enable row level security;
alter table public.delivery_assignments enable row level security;
alter table public.delivery_proofs enable row level security;
alter table public.support_tickets enable row level security;
alter table public.audit_logs enable row level security;
alter table public.notification_outbox enable row level security;
alter table public.service_areas enable row level security;
alter table public.delivery_zones enable row level security;

create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists (select 1 from public.user_roles ur where ur.user_id = auth.uid() and ur.role = 'admin') $$;
create or replace function public.is_merchant_owner(merchant_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists (select 1 from public.merchants m where m.id = merchant_id and m.owner_id = auth.uid()) or public.is_admin() $$;
create or replace function public.is_rider_user(rider_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists (select 1 from public.riders r where r.id = rider_id and r.user_id = auth.uid()) or public.is_admin() $$;

create policy profiles_select_own_or_admin on public.profiles for select using (auth.uid() = id or public.is_admin());
create policy profiles_update_own on public.profiles for update using (auth.uid() = id or public.is_admin());
create policy roles_select_own_or_admin on public.user_roles for select using (auth.uid() = user_id or public.is_admin());
create policy addresses_all_own on public.customer_addresses for all using (auth.uid() = customer_id or public.is_admin()) with check (auth.uid() = customer_id or public.is_admin());
create policy merchants_owner_read on public.merchants for select using (owner_id = auth.uid() or public.is_admin());
create policy merchants_owner_update on public.merchants for update using (owner_id = auth.uid() or public.is_admin()) with check (owner_id = auth.uid() or public.is_admin());
create policy stores_public_approved on public.stores for select using ((is_approved and public.merchants.approval_status = 'approved') or public.is_merchant_owner(merchant_id) or public.is_admin());
create policy stores_merchant_update on public.stores for update using (public.is_merchant_owner(merchant_id)) with check (public.is_merchant_owner(merchant_id));
create policy products_public_approved on public.products for select using ((is_approved and is_available and exists (select 1 from public.stores s where s.id = store_id and s.is_approved)) or public.is_merchant_owner((select merchant_id from public.stores s where s.id = store_id)) or public.is_admin());
create policy products_merchant_manage on public.products for all using (public.is_merchant_owner((select merchant_id from public.stores s where s.id = store_id))) with check (public.is_merchant_owner((select merchant_id from public.stores s where s.id = store_id)));
create policy categories_public_read on public.categories for select using (true);
create policy order_groups_customer_read on public.order_groups for select using (customer_id = auth.uid() or public.is_admin());
create policy orders_customer_read on public.orders for select using (exists (select 1 from public.order_groups g where g.id = order_group_id and g.customer_id = auth.uid()) or public.is_merchant_owner(merchant_id) or public.is_admin());
create policy order_items_order_read on public.order_items for select using (exists (select 1 from public.orders o where o.id = order_id and (exists (select 1 from public.order_groups g where g.id = o.order_group_id and g.customer_id = auth.uid()) or public.is_merchant_owner(o.merchant_id))) or public.is_admin());
create policy order_events_read_participants on public.order_events for select using (order_group_id in (select id from public.order_groups where customer_id = auth.uid()) or order_id in (select id from public.orders where public.is_merchant_owner(merchant_id)) or public.is_admin());
create policy payments_customer_read on public.payments for select using (exists (select 1 from public.order_groups g where g.id = order_group_id and g.customer_id = auth.uid()) or public.is_admin());
create policy payment_events_admin_read on public.payment_events for select using (public.is_admin());
create policy ledger_merchant_read_own on public.ledger_entries for select using ((account_id in (select la.id from public.ledger_accounts la join public.merchants m on m.id = la.owner_id where la.owner_type='merchant' and public.is_merchant_owner(m.id))) or public.is_admin());
create policy refunds_admin_read on public.refunds for select using (public.is_admin() or exists (select 1 from public.payments p join public.order_groups g on g.id = p.order_group_id where p.id = payment_id and g.customer_id = auth.uid()));
create policy settlements_merchant_read on public.merchant_settlements for select using (public.is_merchant_owner(merchant_id) or public.is_admin());
create policy delivery_rider_read on public.delivery_assignments for select using (public.is_rider_user(rider_id) or public.is_admin());
create policy support_customer_insert on public.support_tickets for insert with check (customer_id = auth.uid() or public.is_admin());
create policy audit_admin_read on public.audit_logs for select using (public.is_admin());
create policy service_areas_public_read on public.service_areas for select using (true);
create policy delivery_zones_public_read on public.delivery_zones for select using (true);
